s=json.loads(Path('inputs/凡人修仙传-三段原文.json').read_text(encoding='utf-8'))
A=e['expectedA']
variants={f'C{c[\"number\"]}':{'title':c['title'],'body':c['body']} for c in t['chapters']}
variants['A']=A
for k in ['post','after']:
 variants['A+'+k]={f:A[f]+e['edits'][k][f] for f in ['title','body']}
variants['A+post+get']={f:A[f]+e['edits']['post'][f]+e['edits']['get'][f] for f in ['title','body']}
def valref(field,value):
 for k,v in variants.items():
  if value==v[field]:return k
 if not value:return 'EMPTY'
 return {'UNMATCHED':value}
def pairref(v):
 return {f:valref(f,v[f]['value']) for f in ['title','body']} if 'value' in v.get('title',{}) else {f:valref(f,v[f]) for f in ['title','body']}
def page(p):
 return {'pair':pairref(p['fields']),'remoteBody':valref('body',p['fields']['remote']['value']),
 'editable':[p['fields'][f].get('editable') for f in ['title','body']],
 'disabled':[p['fields'][f]['disabled'] for f in ['title','body']],
 'buttons':[{k:b[k] for k in ['id','chapter','disabled','visible'] if k in b} for b in p['buttons']],
 **{k:p[k] for k in ['message','errorCode','revision','editState','comparison'] if k in p}}
for c in t['chapters']:
 src=next(x for x in s['sources'] if x['id']==c['sourceSegmentId'])
 print('SOURCE',c['number'],c['sourceSegmentId'],c['body']==src['text'],hashlib.sha256(c['body'].encode()).hexdigest()==c['sourceBodySha256'])
for p in sorted(base.glob('*完整业务核心.json')):
 r=json.loads(p.read_text(encoding='utf-8')); orig=json.loads(Path(r['original']['path']).read_text(encoding='utf-8'))
 print('\\n===',p.name,'===')
 print('metadata',json.dumps({'id':r['id'],'scenario':r['scenario'],'passed':r['passed'],'gitBefore':r['environment']['gitBefore'],'gitAfter':r['environment']['gitAfter'],'sourceApp':orig['sources']['prototype/app.js']['sha256'],'inputsMatch':r['inputs']=={'initialization':t,'expectation':e},'A_match':r['independentExpectedA']==A,'recordInputsMatch':r['inputs']==orig['inputs'],'allBusinessCoreSharedFieldsMatchOriginal':{k:r[k]==orig[k] for k in ['id','scenario','passed','environment','inputs','independentExpectedA','gates','service','databases','assertions','environmentErrors','observationErrors','cleanupErrors','sourceChanges']},'unfinished':orig['unfinished'],'errors':{k:orig[k] for k in ['environmentErrors','observationErrors','recordingErrors','cleanupErrors','pageErrors','sourceChanges']},'assertionCount':len(r['assertions']),'failed':[x['name'] for x in r['assertions'] if not x['passed']]},ensure_ascii=False))
 for name,o in r['observed'].items():
  if 'phase' in o:
   print(name,json.dumps({'input':o['input'],'after':page(o['after']),'fields':{f:{'beforePair':pairref(v['before']['fields']),'disabled':v['before']['fields'][f]['disabled'],'editable':v['before']['fields'][f].get('editable'),'focus':v['focused']['focus']['id'],'afterPair':pairref(v['after']['fields'])} for f,v in o['fields'].items()}},ensure_ascii=False))
  elif 'fields' in o: print(name,json.dumps(page(o),ensure_ascii=False))
  elif 'page' in o:print(name,json.dumps({'page':page(o['page']),'servicePosts':o['servicePostCount'],'databaseLabel':o['database']['label']},ensure_ascii=False))
  else:print(name,json.dumps(o,ensure_ascii=False))
