=== prototype/app.js ===
   1: const $=id=>document.getElementById(id);
   2: const parameters=new URLSearchParams(location.search);
   3: let workId=parameters.get('work'),snapshot=null,selected=Number(parameters.get('chapter')??1),busy=false,uncertain=false;
   4: const edits=new Map();
   5: let pendingRemote=null;
   6: function message(text,kind='normal',read=false,code=''){$('message').textContent=text;$('message').dataset.kind=kind;$('read-current').hidden=!read;$('error-detail').hidden=!code;$('error-code').textContent=code;$('error-detail').open=false;}
