def norm(v):
 if isinstance(v,dict): return {k:norm(w) for k,w in v.items()}
 if isinstance(v,list): return [norm(w) for w in v]
 if isinstance(v,str):
  for c in t['chapters']:
   if v==c['body']:return '@FULL_C'+str(c['number'])+'_BODY'
  if v==A['body']:return '@FULL_A_BODY'
  if v==t['work']:return '@WORK'
  if v.startswith('{'):
   try:return {'@parsedJSON':norm(json.loads(v))}
   except ValueError: pass
 return v
