=== prototype/app.js ===
   1: const $=id=>document.getElementById(id);
   2: const parameters=new URLSearchParams(location.search);
   3: let workId=parameters.get('work'),snapshot=null,selected=Number(parameters.get('chapter')??1),busy=false,uncertain=false;
   4: const edits=new Map();
   5: let pendingRemote=null;
   6: function message(text,kind='normal',read=false,code=''){$('message').textContent=text;$('message').dataset.kind=kind;$('read-current').hidden=!read;$('error-detail').hidden=!code;$('error-code').textContent=code;$('error-detail').open=false;}
   7: function failure(error){const text=error.code==='STALE_CHAPTER'?'这一章已保存了新稿。':error.code==='STALE_WORK'?'作品资料已有变化。':error.code?.startsWith('STALE_')?'前文章节已有变化。':error.code==='NETWORK_UNCONFIRMED'?'连接中断，尚未确认保存结果。':error.message;message(text+' 本地修改仍保留，请读取当前稿后对照。','error',true,error.code);}
   8: async function request(path,options){let response;try{response=await fetch(path,options);}catch{const error=new Error('无法连接服务。本次请求未确认，本地修改仍保留；恢复连接后先读取当前稿。');error.code='NETWORK_UNCONFIRMED';throw error;}const value=await response.json();if(!response.ok){const error=new Error(value.error.message);error.code=value.error.code;throw error;}return value;}
   9: function edit(){return edits.get(selected);}
